/bin/zsh -lc "python3 - <<'PY'
import json, pathlib
for f in ['policy.json','coordination.json','source.json']:
 p=pathlib.Path(f); d=json.loads(p.read_text()); print('\\nFILE',f,'bytes',p.stat().st_size,'type',type(d).__name__)
 if f"'!='"'source.json': print(json.dumps(d,ensure_ascii=False,indent=2))
 else:
  print('keys',list(d) if isinstance(d,dict) else 'array')
  a=d if isinstance(d,list) else next((v for v in d.values() if isinstance(v,list)),[])
  for i,x in enumerate(a): print(i, {k:v for k,v in x.items() if k not in ['source_xml','source_notes_xml']},'XML',len(x.get('source_xml','')),'NOTES',len(x.get('source_notes_xml','') or ''))
PY"

